/* ---------------------------------------------------------
   SCORING (shared by both quizzes)
--------------------------------------------------------- */

function tagScoresFromAnswers(questions, answers) {
  const scores = {};
  questions.forEach((q) => {
    if (!(q.left.tag in scores)) scores[q.left.tag] = 0;
    if (!(q.right.tag in scores)) scores[q.right.tag] = 0;
  });
  questions.forEach((q) => {
    const v = answers[q.id] ?? 3;
    scores[q.left.tag] += Math.max(0, 3 - v);
    scores[q.right.tag] += Math.max(0, v - 3);
  });
  return scores;
}

function scoreProfiles(tagScores, profiles) {
  return profiles.map((p) => {
    const entries = Object.entries(p.weights);
    const weightSum = entries.reduce((s, [, w]) => s + w, 0);
    const scoreSum = entries.reduce((s, [tag, w]) => s + (tagScores[tag] || 0) * w, 0);
    const score = weightSum ? scoreSum / weightSum : 0;
    const topTags = entries
      .map(([tag, w]) => ({ tag, contribution: (tagScores[tag] || 0) * w }))
      .filter((t) => t.contribution > 0)
      .sort((a, b) => b.contribution - a.contribution)
      .slice(0, 2)
      .map((t) => t.tag);
    return { ...p, score, topTags };
  });
}

function computeDiscoveryResults(answers) {
  const tagScores = tagScoresFromAnswers(QUESTIONS, answers);
  const modalityScores = scoreProfiles(tagScores, MODALITIES);

  const worlds = WORLD_ORDER.map((id) => {
    const mods = modalityScores.filter((m) => m.worldId === id).sort((a, b) => b.score - a.score);
    return { id, worldScore: mods[0] ? mods[0].score : 0, modalities: mods };
  });

  const maxWorldScore = Math.max(...worlds.map((w) => w.worldScore), 0.0001);
  const leveled = worlds.map((w) => {
    const ratio = w.worldScore / maxWorldScore;
    const level = ratio >= 0.82 ? "Strong" : ratio >= 0.55 ? "Moderate" : "Curious";
    return { ...w, level };
  });

  const ranked = [...modalityScores].sort((a, b) => b.score - a.score);
  const recommendations = ranked.slice(0, 4);

  const weakest = [...leveled].sort((a, b) => a.worldScore - b.worldScore)[0];
  const outsideMatch =
    weakest.modalities.find((m) => !recommendations.some((r) => r.id === m.id)) || weakest.modalities[0];

  return { worlds: leveled, recommendations, outsideMatch };
}

function computeCareerResults(answers) {
  const tagScores = tagScoresFromAnswers(CAREER_QUESTIONS, answers);
  const scored = scoreProfiles(tagScores, CAREER_PROFILES);
  const ranked = [...scored].sort((a, b) => b.score - a.score);
  const maxScore = Math.max(...ranked.map((r) => r.score), 0.0001);
  const leveled = ranked.slice(0, 5).map((r) => {
    const ratio = r.score / maxScore;
    const level = ratio >= 0.82 ? "Strong" : ratio >= 0.55 ? "Moderate" : "Curious";
    return { ...r, level };
  });
  return { ranked: leveled };
}

function computeWorldQuizResult(worldId, answers) {
  const questions = WORLD_QUIZZES[worldId];
  let total = 0;
  let minPossible = 0;
  let maxPossible = 0;
  const vak = { visual: 0, auditory: 0, kinesthetic: 0 };

  questions.forEach((q) => {
    if (q.type === "scale") {
      const v = answers[q.id] ?? 3;
      total += v - 3;
      minPossible += -2;
      maxPossible += 2;
    } else {
      const opt = q.options.find((o) => o.id === answers[q.id]);
      total += opt ? opt.points : 0;
      if (opt) vak[opt.channel] = (vak[opt.channel] || 0) + 1;
      const optPoints = q.options.map((o) => o.points);
      minPossible += Math.min(...optPoints);
      maxPossible += Math.max(...optPoints);
    }
  });

  const ratio = maxPossible > minPossible ? (total - minPossible) / (maxPossible - minPossible) : 0.5;
  const level = ratio >= 0.66 ? "Well suited" : ratio >= 0.4 ? "Somewhat suited" : "Less suited";
  return { level, vak };
}

function whyText(item) {
  const shortName = item.name.split(" — ")[0];
  const phrases = item.topTags.map((t) => TAG_PHRASES[t]).filter(Boolean);
  if (phrases.length === 0) return `${shortName} may be worth exploring based on your overall preferences.`;
  if (phrases.length === 1) return `You leaned toward ${phrases[0]}. ${shortName} may be worth exploring.`;
  return `You leaned toward ${phrases[0]} and ${phrases[1]}. ${shortName} may be worth exploring.`;
}

/* ---------------------------------------------------------
   PERSISTENCE
   Prefers the Claude artifact storage API when available (inside
   Claude, this is always used). Falls back to plain browser
   localStorage when that API doesn't exist — which is the case
   once this app is deployed to real hosting outside Claude. Every
   call is wrapped so a missing storage layer never breaks the app.
--------------------------------------------------------- */

const LOCAL_STORAGE_PREFIX = "discover-therapy:";

function hasClaudeStorage() {
  return typeof window !== "undefined" && !!window.storage;
}

function hasLocalStorage() {
  try {
    return typeof window !== "undefined" && !!window.localStorage;
  } catch (e) {
    return false;
  }
}

async function loadJSON(key) {
  if (hasClaudeStorage()) {
    try {
      const res = await window.storage.get(key, false);
      return res ? JSON.parse(res.value) : null;
    } catch (e) {
      return null;
    }
  }
  if (hasLocalStorage()) {
    try {
      const raw = window.localStorage.getItem(LOCAL_STORAGE_PREFIX + key);
      return raw ? JSON.parse(raw) : null;
    } catch (e) {
      return null;
    }
  }
  return null;
}

async function saveJSON(key, value) {
  if (hasClaudeStorage()) {
    try {
      await window.storage.set(key, JSON.stringify(value), false);
    } catch (e) {
      /* best-effort */
    }
    return;
  }
  if (hasLocalStorage()) {
    try {
      window.localStorage.setItem(LOCAL_STORAGE_PREFIX + key, JSON.stringify(value));
    } catch (e) {
      /* best-effort */
    }
  }
}

async function deleteKey(key) {
  if (hasClaudeStorage()) {
    try {
      await window.storage.delete(key, false);
    } catch (e) {
      /* best-effort */
    }
    return;
  }
  if (hasLocalStorage()) {
    try {
      window.localStorage.removeItem(LOCAL_STORAGE_PREFIX + key);
    } catch (e) {
      /* best-effort */
    }
  }
}

