function Motif({ worldId, size = 40 }) {
  const color = WORLD_META[worldId].color;
  const common = { width: size, height: size, viewBox: "0 0 60 60", xmlns: "http://www.w3.org/2000/svg" };

  if (worldId === "conscious") {
    return (
      <svg {...common} className="td-motif">
        <g fill="none" stroke={color} strokeWidth="1.6">
          <line x1="14" y1="46" x2="30" y2="16" />
          <line x1="30" y1="16" x2="48" y2="30" />
          <line x1="48" y1="30" x2="30" y2="50" />
          <line x1="30" y1="50" x2="14" y2="46" />
          <line x1="30" y1="16" x2="30" y2="50" />
        </g>
        <g fill={color}>
          <circle cx="14" cy="46" r="2.6" />
          <circle cx="30" cy="16" r="2.6" />
          <circle cx="48" cy="30" r="2.6" />
          <circle cx="30" cy="50" r="2.6" />
        </g>
      </svg>
    );
  }
  if (worldId === "subconscious") {
    return (
      <svg {...common} className="td-motif">
        <circle cx="30" cy="32" r="22" fill={color} opacity="0.16" />
        <circle cx="24" cy="36" r="14" fill={color} opacity="0.28" />
        <circle cx="36" cy="24" r="9" fill={color} opacity="0.45" />
      </svg>
    );
  }
  if (worldId === "somatic") {
    return (
      <svg {...common} className="td-motif">
        <path d="M6,36 C14,20 22,52 30,36 C38,20 46,52 54,36" fill="none" stroke={color} strokeWidth="2.4" strokeLinecap="round" />
        <path d="M6,44 C14,30 22,58 30,44 C38,30 46,58 54,44" fill="none" stroke={color} strokeWidth="1.6" opacity="0.4" strokeLinecap="round" />
      </svg>
    );
  }
  return (
    <svg {...common} className="td-motif">
      <circle cx="30" cy="30" r="6" fill={color} />
      <circle cx="30" cy="30" r="14" fill="none" stroke={color} strokeWidth="1.6" opacity="0.55" />
      <circle cx="30" cy="30" r="22" fill="none" stroke={color} strokeWidth="1.4" opacity="0.3" />
    </svg>
  );
}


