function QuizScreen({ questions, sections, qIndex, answers, onSelect, onNext, onBack, onExit, finalLabel }) {
  const q = questions[qIndex];
  const total = questions.length;
  const percent = Math.round((qIndex / total) * 100);
  const selected = answers[q.id];

  return (
    <div>
      <button className="td-exit" onClick={onExit}>Exit</button>

      <p className="td-progress-label">{sections[q.section]}</p>
      <p className="td-progress-sub">Question {qIndex + 1} of {total}</p>
      <div className="td-progress-track">
        <div className="td-progress-fill" style={{ width: `${percent}%` }} />
      </div>

      <div className="td-question" key={q.id}>
        <h2>Which side feels more like you?</h2>
        <div className="td-scale">
          <div className="td-scale-labels">
            <span>{q.left.label}</span>
            <span>{q.right.label}</span>
          </div>
          <div className="td-scale-row" role="radiogroup" aria-label="Answer scale">
            {[1, 2, 3, 4, 5].map((n) => (
              <button
                key={n}
                className={`td-scale-option${selected === n ? " is-selected" : ""}`}
                aria-pressed={selected === n}
                aria-label={`${n} of 5`}
                onClick={() => onSelect(q.id, n)}
              />
            ))}
          </div>
        </div>
      </div>

      <div className="td-quiz-nav">
        <button className="td-btn-secondary" onClick={onBack}>Back</button>
        <button className="td-btn-primary" onClick={onNext} disabled={!selected}>
          {qIndex === total - 1 ? finalLabel : "Continue"}
        </button>
      </div>
    </div>
  );
}

