function ReflectionExercise({ prompts, closingNote, trackId }) {
  const [answers, setAnswers] = useState(prompts.map(() => ""));
  const [done, setDone] = useState(false);
  const allFilled = answers.every((a) => a.trim().length > 0);

  if (done) {
    return (
      <div className="td-exercise-complete">
        <p className="td-exercise-complete-title">Nicely done.</p>
        <p className="td-detail-text">{closingNote}</p>
        <button className="td-qual-toggle" onClick={() => { setAnswers(prompts.map(() => "")); setDone(false); }}>
          Try again
        </button>
      </div>
    );
  }

  return (
    <div className="td-exercise">
      {prompts.map((p, i) => (
        <div key={i} className="td-exercise-field">
          <p className="td-exercise-label">{p}</p>
          <input
            className="td-exercise-input"
            type="text"
            value={answers[i]}
            onChange={(e) => {
              const next = [...answers];
              next[i] = e.target.value;
              setAnswers(next);
            }}
          />
        </div>
      ))}
      <button
        className="td-btn-primary"
        disabled={!allFilled}
        onClick={() => { setDone(true); track("exercise_completed", { modality: trackId }); }}
      >
        Reflect
      </button>
    </div>
  );
}

function StepsExercise({ steps, closingNote, showReflection, trackId }) {
  const [step, setStep] = useState(0);
  const [done, setDone] = useState(false);
  const [reflection, setReflection] = useState("");

  if (done) {
    return (
      <div className="td-exercise-complete">
        <p className="td-exercise-complete-title">Well done.</p>
        <p className="td-detail-text">{closingNote}</p>
        {showReflection && (
          <textarea
            className="td-exercise-textarea"
            placeholder="Optional: what came up for you? (stays on this device only)"
            value={reflection}
            onChange={(e) => setReflection(e.target.value)}
          />
        )}
        <button className="td-qual-toggle" onClick={() => { setStep(0); setDone(false); setReflection(""); }}>
          Try again
        </button>
      </div>
    );
  }

  return (
    <div className="td-exercise">
      <p className="td-mini-q-number">Step {step + 1} of {steps.length}</p>
      <p className="td-exercise-step-text">{steps[step]}</p>
      <button
        className="td-btn-primary"
        onClick={() => {
          if (step < steps.length - 1) setStep((s) => s + 1);
          else { setDone(true); track("exercise_completed", { modality: trackId }); }
        }}
      >
        {step < steps.length - 1 ? "Continue" : "Finish"}
      </button>
    </div>
  );
}

function TimedExercise({ phases, cycles, closingNote, trackId }) {
  const [running, setRunning] = useState(false);
  const [phaseIndex, setPhaseIndex] = useState(0);
  const [secondsLeft, setSecondsLeft] = useState(phases[0].seconds);
  const [cycle, setCycle] = useState(1);
  const [done, setDone] = useState(false);

  useEffect(() => {
    if (!running) return undefined;
    const id = setInterval(() => setSecondsLeft((s) => s - 1), 1000);
    return () => clearInterval(id);
  }, [running]);

  useEffect(() => {
    if (!running || secondsLeft > 0) return;
    const nextIndex = (phaseIndex + 1) % phases.length;
    if (nextIndex === 0) {
      const nextCycle = cycle + 1;
      if (nextCycle > cycles) {
        setRunning(false);
        setDone(true);
        track("exercise_completed", { modality: trackId });
        return;
      }
      setCycle(nextCycle);
    }
    setPhaseIndex(nextIndex);
    setSecondsLeft(phases[nextIndex].seconds);
  }, [secondsLeft, running]);

  const start = () => {
    setPhaseIndex(0);
    setSecondsLeft(phases[0].seconds);
    setCycle(1);
    setDone(false);
    setRunning(true);
    track("exercise_started", { modality: trackId });
  };

  const phase = phases[phaseIndex];

  if (done) {
    return (
      <div className="td-exercise-complete">
        <p className="td-exercise-complete-title">Well done.</p>
        <p className="td-detail-text">{closingNote}</p>
        <button className="td-qual-toggle" onClick={start}>Do it again</button>
      </div>
    );
  }

  return (
    <div className="td-exercise">
      <div className="td-breath-stage">
        <div
          className="td-breath-bubble"
          style={{
            transform: `scale(${running ? phase.scale : 1})`,
            transitionDuration: `${phase.seconds}s`,
          }}
        >
          <span className="td-breath-count">{running ? secondsLeft : ""}</span>
        </div>
      </div>
      <p className="td-breath-label">{running ? phase.label : "Ready when you are"}</p>
      {running && cycles > 1 && <p className="td-helper-text">Round {cycle} of {cycles}</p>}
      {!running && (
        <button className="td-btn-primary" onClick={start}>Start</button>
      )}
    </div>
  );
}

function ChecklistExercise({ steps, closingNote, trackId }) {
  const [checked, setChecked] = useState(() => steps.map(() => false));
  const allDone = checked.every(Boolean);

  const toggle = (i) => {
    const next = [...checked];
    next[i] = !next[i];
    setChecked(next);
    if (next.every(Boolean)) track("exercise_completed", { modality: trackId });
  };

  return (
    <div className="td-exercise">
      <div className="td-clearing-list">
        {steps.map((s, i) => (
          <button
            key={i}
            className={`td-clearing-step${checked[i] ? " is-done" : ""}`}
            onClick={() => toggle(i)}
            aria-pressed={checked[i]}
          >
            <span className="td-clearing-check">{checked[i] ? "\u2713" : ""}</span>
            <span>{s}</span>
          </button>
        ))}
      </div>
      {allDone && (
        <p className="td-exercise-complete-title" style={{ marginTop: "16px" }}>{closingNote}</p>
      )}
    </div>
  );
}

